insert into public.projects (id, slug, name, summary, logo, external, stats, body, facts, photos, partners, sort) values
  ('focsani-tech-challenge', 'focsani-tech-challenge', '{"en":"Focșani Tech Challenge","ro":"Focșani Tech Challenge"}'::jsonb, '{"en":"A league meet we organise every year to bring the teams from our area to our town.","ro":"O etapă de ligă pe care o organizăm în fiecare an, ca să aducem echipele din zonă în orașul nostru."}'::jsonb, null, null, '[]'::jsonb, '{"en":[],"ro":[]}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 0),
  ('brick-by-brick-school', 'brick-by-brick-school', '{"en":"Brick By Brick School","ro":"Brick By Brick School"}'::jsonb, '{"en":"Our structured preparation programme for new recruits.","ro":"Programul nostru structurat de pregătire pentru recruți."}'::jsonb, null, null, '[]'::jsonb, '{"en":[],"ro":[]}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 1),
  ('brickbot-caravan', 'brickbot-caravan', '{"en":"BrickBot Caravan","ro":"BrickBot Caravan"}'::jsonb, '{"en":"A series of visits and presentations in the schools of our town.","ro":"O serie de vizite și prezentări în școlile din orașul nostru."}'::jsonb, null, null, '[]'::jsonb, '{"en":[],"ro":[]}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 2),
  ('first-steps-into-steam', 'first-steps-into-steam', '{"en":"FIRST Steps Into STEAM","ro":"FIRST Steps Into STEAM"}'::jsonb, '{"en":"Technical and non-technical workshops that introduce secondary school students from rural areas to STEAM education.","ro":"Ateliere tehnice și non-tehnice prin care le prezentăm educația STEAM elevilor de gimnaziu din mediul rural."}'::jsonb, null, null, '[]'::jsonb, '{"en":[],"ro":[]}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 3),
  ('ftc-sparks', 'ftc-sparks', '{"en":"FTC Sparks","ro":"FTC Sparks"}'::jsonb, '{"en":"Online meetups with teams from all over the world, where we share our experiences and perspectives.","ro":"Întâlniri online cu echipe din toată lumea, în care ne împărtășim experiențele și perspectivele."}'::jsonb, null, null, '[]'::jsonb, '{"en":[],"ro":[]}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 4),
  ('brickdocs', 'brickdocs', '{"en":"BrickDocs","ro":"BrickDocs"}'::jsonb, '{"en":"Our documentation platform, where we collect everything we know.","ro":"Platforma noastră de documentație, unde adunăm tot ce știm."}'::jsonb, null, 'https://docs.brickbot.ro', '[]'::jsonb, '{"en":[],"ro":[]}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 5)
