insert into public.timeline_milestones (id, occurred_on, title, text, image) values
  ('2016-team-15996-is-born', '2016', '{"en":"Team #15996 is born","ro":"Se naște echipa #15996"}'::jsonb, '{"en":"Students at “Unirea” National College start the first FIRST Tech Challenge team in Vrancea county.","ro":"Elevi de la Colegiul Național „Unirea” pornesc prima echipă FIRST Tech Challenge din județul Vrancea."}'::jsonb, null),
  ('2019-national-finalists', '2019', '{"en":"National finalists","ro":"Finaliști la Național"}'::jsonb, '{"en":"In Rover Ruckus we reach the final of the Romania National Championship, win the Romania Moldova Regional and have a Dean’s List finalist.","ro":"În Rover Ruckus ajungem în finala Campionatului Național, câștigăm Regionala Moldova și avem un finalist Dean’s List."}'::jsonb, null),
  ('2021-inspire-award', '2021', '{"en":"Inspire Award","ro":"Inspire Award"}'::jsonb, '{"en":"The top award in FTC, at a Romanian qualifying tournament, plus the Innovate Award, 2nd place, at the National Championship.","ro":"Cel mai important premiu din FTC, la un turneu de calificare, plus locul 2 la Innovate Award la Campionatul Național."}'::jsonb, null),
  ('2023-our-second-dean-s-list-finalist', '2023', '{"en":"Our second Dean’s List Finalist","ro":"Al doilea Dean’s List Finalist"}'::jsonb, '{"en":"In POWERPLAY one of our members reaches the Dean’s List finals.","ro":"În POWERPLAY unul dintre membrii noștri ajunge în finala Dean’s List."}'::jsonb, null),
  ('2025-abroad-in-schools-and-a-cup', '2025', '{"en":"Abroad, in schools, and a cup","ro":"În străinătate, în școli și o cupă"}'::jsonb, '{"en":"The Innovate Award, 2nd place, at the Italy Championship, robotics lessons in Focșani primary schools, and the SparkHope Robotics Cup title.","ro":"Locul 2 la Innovate Award la Campionatul Italiei, lecții de robotică în școlile primare din Focșani și titlul la SparkHope Robotics Cup."}'::jsonb, null),
  ('2026-world-championship', '2026', '{"en":"World championship","ro":"Campionatul Mondial"}'::jsonb, '{"en":"DECODE takes us to the FIRST Championship in Houston: division finalists, Design Award 2nd place, and a season in the world’s top 10.","ro":"DECODE ne duce la Campionatul Mondial FIRST din Houston: finaliști de divizie, locul 2 la Design Award și un sezon în top 10 mondial."}'::jsonb, null)
insert into public.team_page (id, mission, drive, "values", students_do, team_photo) values
  (1, '{"en":"Our goal is simple: build a robot that can compete with anyone, and use it to get more young people in Vrancea into science and engineering. Four things keep us going.","ro":"Scopul nostru e simplu: un robot care să se poată bate cu oricine și, prin el, mai mulți tineri din Vrancea atrași de știință și inginerie. Patru lucruri ne țin în priză."}'::jsonb, '{"en":"High-school students from Focșani who build a competition robot every year, and everything around it, with nobody doing it for them.","ro":"Liceeni din Focșani care construiesc în fiecare an un robot de competiție, și tot ce ține de el, fără ca altcineva să o facă în locul lor."}'::jsonb, '[{"name":{"en":"Outreach","ro":"Outreach"},"line":{"en":"A robot is the best excuse to get kids curious. We take ours into schools and public events every year.","ro":"Un robot e cea mai bună scuză ca să-i faci pe copii curioși. Îl ducem în școli și la evenimente publice în fiecare an."}},{"name":{"en":"Creativity","ro":"Creativitate"},"line":{"en":"Every game is new, so every robot starts from a blank page. The weird ideas are usually the good ones.","ro":"Fiecare joc e nou, deci fiecare robot pornește de la o foaie albă. Ideile ciudate sunt de obicei cele bune."}},{"name":{"en":"Ambition","ro":"Ambiție"},"line":{"en":"We aim for the world stage, and in 2026 we got there.","ro":"Țintim scena mondială, iar în 2026 am ajuns acolo."}},{"name":{"en":"Team spirit","ro":"Spirit de echipă"},"line":{"en":"Older members teach newer ones, and nobody wins or loses alone.","ro":"Cei mai vechi îi învață pe cei noi și nimeni nu câștigă sau pierde singur."}}]'::jsonb, '{"en":"Nobody here is just “on the team”. In a season, our members:\n\n- design parts in CAD, then machine, print and assemble them\n- write the code that drives the robot, autonomous routines included\n- drive it under pressure, in front of a full hall\n- write and design an engineering portfolio judged against teams from all over the world\n- run our social media, shoot photo and video, and design everything you see from us\n- organise events, teach robotics to primary-school kids and pitch to sponsors","ro":"Nimeni nu e aici doar „în echipă”. Într-un sezon, membrii noștri:\n\n- proiectează piese în CAD, apoi le prelucrează, le printează și le asamblează\n- scriu codul care conduce robotul, inclusiv rutinele autonome\n- îl pilotează sub presiune, în fața unei săli pline\n- scriu și designează un portofoliu de inginerie jurizat alături de echipe din toată lumea\n- se ocupă de social media, fac foto și video și designează tot ce vezi de la noi\n- organizează evenimente, predau robotică copiilor de la primară și prezintă echipa sponsorilor"}'::jsonb, 'seasons/biobuzz/team-photo.webp')
