insert into public.join_page (id, requirements) values
  (1, '{"en":"- You study at “Unirea” National College in Focșani.\n- You’re at least 13 years old.\n- That’s it. No prior experience needed: you start as a recruit and we teach you the rest.","ro":"- Înveți la Colegiul Național „Unirea” din Focșani.\n- Ai cel puțin 13 ani.\n- Atât. Nu ai nevoie de experiență: începi ca recrut și te învățăm noi restul."}'::jsonb)
insert into public.departments (id, name, description, photos, sort) values
  ('assembly-3d-design', '{"en":"Assembly & 3D design","ro":"Asamblare și proiectare 3D"}'::jsonb, '{"en":"Design the robot in CAD, then cut, print and bolt it together. If you like taking things apart, start here.","ro":"Proiectezi robotul în CAD, apoi îl tai, îl printezi și îl înșurubezi. Dacă îți place să desfaci lucruri, începe de aici."}'::jsonb, '[]'::jsonb, 0),
  ('programming', '{"en":"Programming","ro":"Programare"}'::jsonb, '{"en":"Write the code that drives the robot, from the driver controls to the autonomous period.","ro":"Scrii codul care conduce robotul, de la controlul pilotului la perioada autonomă."}'::jsonb, '[]'::jsonb, 1),
  ('events', '{"en":"Events","ro":"Evenimente"}'::jsonb, '{"en":"Plan our stands, school visits and meetups, and make them run on the day.","ro":"Plănuiești standurile, vizitele în școli și întâlnirile și le faci să meargă în ziua respectivă."}'::jsonb, '[]'::jsonb, 2),
  ('social-media', '{"en":"Social media","ro":"Social media"}'::jsonb, '{"en":"Tell the team’s story on Instagram, TikTok, Facebook and LinkedIn.","ro":"Spui povestea echipei pe Instagram, TikTok, Facebook și LinkedIn."}'::jsonb, '[]'::jsonb, 3),
  ('graphic-design', '{"en":"Graphic design","ro":"Design grafic"}'::jsonb, '{"en":"Shirts, posters, the engineering portfolio, the robot’s livery: if it has our logo on it, design touched it.","ro":"Tricouri, afișe, portofoliul de inginerie, grafica robotului: dacă are logo-ul nostru, a trecut pe la design."}'::jsonb, '[]'::jsonb, 4),
  ('photo-video', '{"en":"Photo & video","ro":"Foto și video"}'::jsonb, '{"en":"Shoot competitions, edit reels and the season’s videos.","ro":"Fotografiezi competițiile, montezi reel-uri și videoclipurile sezonului."}'::jsonb, '[]'::jsonb, 5),
  ('fundraising', '{"en":"Fundraising","ro":"Fundraising"}'::jsonb, '{"en":"Find sponsors, pitch the team and manage the partnerships that pay for the season.","ro":"Găsești sponsori, prezinți echipa și te ocupi de parteneriatele care plătesc sezonul."}'::jsonb, '[]'::jsonb, 6)
