insert into public.support_docs (id, contract, contract_text) values
  (1, null, '{"en":"1. **Get in touch.** Tell us which package you’re thinking of, or what you’d like to offer instead.\n2. **We send the contract.** A sponsorship contract between your company and Asociația BrickBot, with the benefits written in.\n3. **Sign and transfer.** Payment goes to the association’s account at Banca Transilvania. No middlemen.\n4. **We deliver, all season.** Your logo goes on everything your package covers, and we keep you posted from every competition.","ro":"1. **Ne scrii.** Spune-ne la ce pachet te gândești sau ce ai vrea să oferi în schimb.\n2. **Îți trimitem contractul.** Un contract de sponsorizare între firma ta și Asociația BrickBot, cu beneficiile trecute în el.\n3. **Semnezi și faci transferul.** Plata ajunge în contul asociației de la Banca Transilvania. Fără intermediari.\n4. **Livrăm tot sezonul.** Logo-ul tău apare peste tot unde prevede pachetul, iar noi te ținem la curent de la fiecare competiție."}'::jsonb)
insert into public.home_hero (id, tagline, intro, media_type, media, poster) values
  (1, '{"en":"We build our future brick by brick!","ro":"Ne construim viitorul cărămidă cu cărămidă!"}'::jsonb, '{"en":"BrickBot is the robotics team of “Unirea” National College in Focșani, and the first FIRST Tech Challenge team in Vrancea county. Every season we design, build and program a new robot, and we run everything around it ourselves: events, design, photo and video, fundraising.","ro":"BrickBot este echipa de robotică a Colegiului Național „Unirea” din Focșani și prima echipă FIRST Tech Challenge din județul Vrancea. În fiecare sezon proiectăm, construim și programăm un robot nou și ne ocupăm singuri de tot ce ține de el: evenimente, design, foto-video, strângere de fonduri."}'::jsonb, 'image', 'site/home/hero.webp', null)
insert into public.faq_items (id, question, answer, sort) values
  ('3b09e8db-c355-1a2b-62b0-4a298c03ee60', '{"en":"Who are we signing with?","ro":"Cu cine semnăm?"}'::jsonb, '{"en":"Asociația BrickBot, the NGO that runs the team (CIF 50846996). Every sponsorship and donation goes to the association, under a written contract.","ro":"Cu Asociația BrickBot, ONG-ul care administrează echipa (CIF 50846996). Fiecare sponsorizare și donație merge către asociație, pe bază de contract scris."}'::jsonb, 0),
  ('b4093ada-b060-aa1b-d2c3-e9cf4a6a9811', '{"en":"How does a sponsorship work?","ro":"Cum funcționează o sponsorizare?"}'::jsonb, '{"en":"You pick a package, or offer products or services instead, and we sign a sponsorship contract between your company and Asociația BrickBot. Write to contact@brickbot.ro and we’ll send you the details.","ro":"Alegi un pachet sau oferi produse ori servicii, iar noi semnăm un contract de sponsorizare între firma ta și Asociația BrickBot. Scrie-ne la contact@brickbot.ro și îți trimitem detaliile."}'::jsonb, 1),
  ('7bc67332-0b35-c99d-3363-36de93ed8f88', '{"en":"Where does the money go?","ro":"Pe ce se duc banii?"}'::jsonb, '{"en":"Into the season: robot parts and tools, field elements to practise on, competition registration fees, and travel to events in Romania and abroad. Our Partner page breaks down last season’s spending, category by category.","ro":"Pe sezon: piese și scule pentru robot, elemente de teren pentru antrenamente, taxe de înscriere la competiții și drumuri la evenimente din țară și din străinătate. Pe pagina de parteneriate găsești cheltuielile sezonului trecut, pe categorii."}'::jsonb, 2),
  ('4d7bbddd-1ae5-3003-7f3b-fc8e4c117ccb', '{"en":"Can we help without money?","ro":"Putem ajuta și fără bani?"}'::jsonb, '{"en":"Yes. You can sponsor with products or services, host a workshop for our team, or invite us and the robot to your school or event.","ro":"Da. Poți sponsoriza cu produse sau servicii, poți ține un atelier pentru echipa noastră sau ne poți invita cu robotul la școala sau evenimentul tău."}'::jsonb, 3),
  ('90a1978a-b2ff-bc61-aee5-804d0fc4ef56', '{"en":"What is FIRST Tech Challenge?","ro":"Ce este FIRST Tech Challenge?"}'::jsonb, '{"en":"A worldwide robotics competition for students aged 12 to 18. Each September a new game is announced, and teams have a few months to design, build and program a robot to play it. In Romania, FTC is run by Nație prin Educație.","ro":"O competiție internațională de robotică pentru elevi între 12 și 18 ani. În fiecare septembrie se anunță un joc nou, iar echipele au câteva luni să proiecteze, să construiască și să programeze un robot care să-l joace. În România, FTC este organizat de Nație prin Educație."}'::jsonb, 4)
insert into public.form230_callout (id, starts_on, ends_on, text, link) values
  (1, '2027-01-01', '2027-05-25', '{"en":"Redirect 3.5% of your income tax to BrickBot with Form 230, until 25 May.","ro":"Redirecționează 3,5% din impozitul pe venit către BrickBot prin Formularul 230, până pe 25 mai."}'::jsonb, 'https://formular230.ro/asociatia-brickbot')
insert into public.press_kit (id, marks, photos, short_description, long_description, contact_email) values
  (1, '{"logoSvgDark":"brand/logo.svg","logoSvgLight":"brand/logo-black.svg","logoPngDark":null,"logoPngLight":null,"wordmarkSvgDark":"brand/wordmark.svg","wordmarkSvgLight":"brand/wordmark-black.svg","wordmarkPngDark":null,"wordmarkPngLight":null}'::jsonb, '[{"id":"site-home-hero","kind":"team","file":"site/home/hero.webp","alt":{"en":"Celebrating at the 2026 Romania National Championship","ro":"Bucurie la Campionatul Național 2026"}},{"id":"seasons-decode-team-photo","kind":"team","file":"seasons/decode/team-photo.webp","alt":{"en":"The team at the 2026 FIRST Championship","ro":"Echipa la Campionatul Mondial FIRST 2026"}},{"id":"gallery-decode-worlds-practice-field","kind":"robot","file":"gallery/decode/worlds-practice-field.webp","alt":{"en":"The DECODE robot on a practice field in Houston","ro":"Robotul DECODE pe un teren de antrenament în Houston"}},{"id":"seasons-biobuzz-team-photo","kind":"team","file":"seasons/biobuzz/team-photo.webp","alt":{"en":"The 2026–27 team","ro":"Echipa 2026–27"}}]'::jsonb, '{"en":"BrickBot (FTC team #15996) is the FIRST Tech Challenge robotics team from Focșani, Romania, with members mainly from “Unirea” National College. Founded in 2016 as the first FTC team in Vrancea county, it finished the 2025–26 season in the world’s top 10 and as a division finalist at the FIRST Championship in Houston.","ro":"BrickBot (echipa FTC #15996) este echipa de robotică FIRST Tech Challenge din Focșani, România, cu membri în principal de la Colegiul Național „Unirea”. Înființată în 2016 ca prima echipă FTC din județul Vrancea, a încheiat sezonul 2025–26 în top 10 mondial și ca finalistă de divizie la Campionatul Mondial FIRST din Houston."}'::jsonb, '{"en":"BrickBot (FTC team #15996) is the FIRST Tech Challenge robotics team from Focșani, Romania, with members mainly from “Unirea” National College, and the first FTC team in Vrancea county. Since 2016, its high-school students have designed, built and programmed a new competition robot every season, and run everything around it themselves: events, graphic design, photo and video, social media and fundraising.\n\nIn the 2025–26 DECODE season the team reached the FIRST Championship in Houston, where it was a division finalist alliance and won 2nd place for the Design Award, finishing the season in the world’s top 10. Earlier results include the SparkHope Robotics Cup title (2025), the Innovate Award, 2nd place, at the Italy Championship (2025) and an Inspire Award in Romania (2021).\n\nThe team also teaches robotics in Focșani primary schools and runs stands at public events. It is run legally by Asociația BrickBot, a Romanian NGO (CIF 50846996).","ro":"BrickBot (echipa FTC #15996) este echipa de robotică FIRST Tech Challenge din Focșani, România, cu membri în principal de la Colegiul Național „Unirea”, și prima echipă FTC din județul Vrancea. Din 2016, liceenii din echipă proiectează, construiesc și programează în fiecare sezon un robot de competiție nou și se ocupă singuri de tot ce ține de el: evenimente, design grafic, foto-video, social media și strângere de fonduri.\n\nÎn sezonul 2025–26 DECODE, echipa a ajuns la Campionatul Mondial FIRST din Houston, unde a fost alianță finalistă a diviziei și a câștigat locul 2 la Design Award, încheind sezonul în top 10 mondial. Printre rezultatele anterioare se numără titlul la SparkHope Robotics Cup (2025), locul 2 la Innovate Award la Campionatul Italiei (2025) și un Inspire Award în România (2021).\n\nEchipa predă și robotică în școlile primare din Focșani și are standuri la evenimente publice. Din punct de vedere legal, este administrată de Asociația BrickBot, ONG înregistrat în România (CIF 50846996)."}'::jsonb, 'contact@brickbot.ro')
